//! Raw bindings of the ProGPU native C ABI (`progpu_native.h`, ABI version 5) and of the
//! wgpu-native WebGPU C ABI (`webgpu.h` with `wgpu.h`, the May-2024 revision the engine is built
//! against), generated by `bindgen` (`regenerate.sh`) and loaded at run time.
//!
//! The libraries come from the ProGPU native SDK packages of this crate's version (see `build.rs`):
//! [`Runtime::load`] opens them from `PROGPU_NATIVE_RUNTIME_DIR` (at run time), the directory of the
//! executable, or the SDK directory the build found.

#![allow(non_camel_case_types, non_snake_case, non_upper_case_globals, dead_code, clippy::all)]

use std::fmt;
use std::path::{Path, PathBuf};

/// The ProGPU native C ABI.
pub mod progpu {
    include!("progpu_native.rs");
}

/// The wgpu-native WebGPU C ABI.
pub mod webgpu {
    include!("webgpu.rs");
}

/// The version of the ProGPU native SDK these bindings are generated from.
pub const SDK_VERSION: &str = "0.1.0-preview.70";

/// The file names of the runtime libraries on this platform.
#[cfg(target_os = "macos")]
const LIBRARIES: (&str, &str) = ("libprogpu_native.dylib", "libwgpu_native.dylib");
#[cfg(target_os = "linux")]
const LIBRARIES: (&str, &str) = ("libprogpu_native.so", "libwgpu_native.so");
#[cfg(windows)]
const LIBRARIES: (&str, &str) = ("progpu_native.dll", "wgpu_native.dll");
#[cfg(not(any(target_os = "macos", target_os = "linux", windows)))]
const LIBRARIES: (&str, &str) = ("", "");

/// Why the runtime libraries could not be loaded.
#[derive(Debug)]
pub enum LoadError {
    /// No runtime directory holds the libraries (or the target has no desktop SDK).
    NotFound(Vec<PathBuf>),
    /// A library was found but could not be loaded.
    Library(PathBuf, libloading::Error),
    /// The engine reports another ABI version than these bindings.
    AbiVersion(u32),
}

impl fmt::Display for LoadError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            LoadError::NotFound(searched) => {
                write!(f, "the ProGPU native runtime {SDK_VERSION} was not found (searched")?;
                for dir in searched {
                    write!(f, " {}", dir.display())?;
                }
                write!(f, ")")
            }
            LoadError::Library(path, error) => write!(f, "{} could not be loaded: {error}", path.display()),
            LoadError::AbiVersion(version) => {
                write!(f, "the ProGPU native runtime has ABI version {version}, the bindings {}", progpu::PROGPU_NATIVE_ABI_VERSION)
            }
        }
    }
}

impl std::error::Error for LoadError {}

/// The loaded runtime libraries: the engine and the WebGPU implementation its handles belong to.
pub struct Runtime {
    /// The ProGPU native engine (`progpu_native`).
    pub progpu: progpu::ProGPUNativeLibrary,
    /// The wgpu-native library (`wgpu_native`) the engine is linked against.
    pub wgpu: webgpu::WgpuNativeLibrary,
    directory: PathBuf,
}

impl Runtime {
    /// The directories searched for the runtime libraries, in order.
    pub fn search_directories() -> Vec<PathBuf> {
        let mut directories = Vec::new();
        if let Some(dir) = std::env::var_os("PROGPU_NATIVE_RUNTIME_DIR") {
            directories.push(PathBuf::from(dir));
        }
        if let Some(dir) = std::env::current_exe().ok().and_then(|exe| exe.parent().map(Path::to_path_buf)) {
            directories.push(dir);
        }
        if let Some(dir) = option_env!("PROGPU_NATIVE_RUNTIME_DIR") {
            directories.push(PathBuf::from(dir));
        }
        directories
    }

    /// Loads the runtime libraries from the first directory of [`search_directories`](Self::search_directories)
    /// that holds them.
    pub fn load() -> Result<Self, LoadError> {
        let directories = Self::search_directories();
        for directory in &directories {
            if !LIBRARIES.0.is_empty() && directory.join(LIBRARIES.0).is_file() && directory.join(LIBRARIES.1).is_file() {
                return Self::load_from(directory);
            }
        }
        Err(LoadError::NotFound(directories))
    }

    /// Loads the runtime libraries from `directory`.
    pub fn load_from(directory: &Path) -> Result<Self, LoadError> {
        let wgpu_path = directory.join(LIBRARIES.1);
        let progpu_path = directory.join(LIBRARIES.0);
        // SAFETY: the libraries are the SDK's; loading runs their initializers only.
        let wgpu = unsafe { webgpu::WgpuNativeLibrary::new(&wgpu_path) }.map_err(|error| LoadError::Library(wgpu_path, error))?;
        let progpu =
            unsafe { progpu::ProGPUNativeLibrary::new(&progpu_path) }.map_err(|error| LoadError::Library(progpu_path, error))?;
        // SAFETY: a plain query without arguments.
        let version = unsafe { progpu.progpu_native_get_abi_version() };
        if version != progpu::PROGPU_NATIVE_ABI_VERSION {
            return Err(LoadError::AbiVersion(version));
        }
        Ok(Self { progpu, wgpu, directory: directory.to_path_buf() })
    }

    /// The directory the libraries were loaded from.
    pub fn directory(&self) -> &Path {
        &self.directory
    }
}
